#include <iostream>
using namespace std;

template <typename... Args>
int addAll(Args... args) {
    return (args + ... + 0);
}

template <typename T, typename... Rest>
int firstThenRest(T first, Rest... rest) {
    cout << "头一个 " << first << endl;
    cout << "后面还有 " << sizeof...(rest) << " 个" << endl;
    return addAll(rest...);
}

int main() {
    int n = 0;
    cin >> n;

    int total = firstThenRest(n, {d1}, {d2});
